// --->> CRON
schedule("* * * * * *", async () => {
  if (getState('0_userdata.0.Bewässerung.Aktiv').val == true) {
    // Korrektur
    if (getState('0_userdata.0.Bewässerung.Restzeit').val > getState('0_userdata.0.Bewässerung.Laufzeit').val) {
      setState('0_userdata.0.Bewässerung.Zähler' /* Zähler */, 0, true);
      setState('0_userdata.0.Bewässerung.Restzeit' /* Restzeit */, getState('0_userdata.0.Bewässerung.Laufzeit').val, true);
      console.debug('Restzeit angepasst');
    }
    // Countdown
    if (getState('0_userdata.0.Bewässerung.Restzeit').val > 0 && getState('0_userdata.0.Bewässerung.Aktiv').val == true) {
      setState('0_userdata.0.Bewässerung.Zähler' /* Zähler */, (getState('0_userdata.0.Bewässerung.Zähler').val + 1), true);
      setState('0_userdata.0.Bewässerung.Restzeit' /* Restzeit */, (getState('0_userdata.0.Bewässerung.Restzeit').val - 1), true);
    }
    // Bewässerung deaktivieren
    if (getState('0_userdata.0.Bewässerung.BewässerungAktiv').val == true) {
      if (getState('0_userdata.0.Bewässerung.Zähler').val == getState('0_userdata.0.Bewässerung.Laufzeit_Vormittag').val && getState('0_userdata.0.Bewässerung.Timezone').val == 1) {
        setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
        setState('0_userdata.0.Bewässerung.BewässerungAktiv' /* BewässerungAktiv */, false);
        console.debug('Bewässerung Vormittag deaktiviert');
      } else if (getState('0_userdata.0.Bewässerung.Zähler').val == getState('0_userdata.0.Bewässerung.Laufzeit_Nachmittag').val && getState('0_userdata.0.Bewässerung.Timezone').val == 2) {
        setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
        setState('0_userdata.0.Bewässerung.BewässerungAktiv' /* BewässerungAktiv */, false);
        console.debug('Bewässerung Nachmittag deaktiviert');
      } else if (getState('0_userdata.0.Bewässerung.Zähler').val == getState('0_userdata.0.Bewässerung.Laufzeit_Abend').val && getState('0_userdata.0.Bewässerung.Timezone').val == 3) {
        setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
        setState('0_userdata.0.Bewässerung.BewässerungAktiv' /* BewässerungAktiv */, false);
        console.debug('Bewässerung Abend deaktiviert');
      }
    }
    // Bewässerung aktivieren
    if (getState('0_userdata.0.Bewässerung.Restzeit').val == 0) {
      // Timezone 1
      if (compareTime('07:00', null, '>=', null) && compareTime('12:00', null, '<', null) && getState('0_userdata.0.Bewässerung.Aktiv').val == true) {
        console.debug('Timezone 1');
        setState('0_userdata.0.Bewässerung.Timezone' /* Timezone */, 1, true);
        if (getState('linktap.0.03444023004B1200.13414023004B1200.InstantModeDuration').val != getState('0_userdata.0.Bewässerung.maxBewässerungszeit').val) {
          setState('linktap.0.03444023004B1200.13414023004B1200.InstantModeDuration' /* Duration for instant mode (min.1  - max. 1439) */, parseFloat(getState('0_userdata.0.Bewässerung.maxBewässerungszeit').val), true);
          console.debug('Duration angepasst');
          await wait(16000);
        }
        if (getState('0_userdata.0.Bewässerung.BewässerungAktiv').val == false) {
          setState('linktap.0.03444023004B1200.13414023004B1200.StartInstantMode' /* Starts instant mode. (Set duration in state 'InstantModeDuration' */, true);
          setState('0_userdata.0.Bewässerung.BewässerungAktiv' /* BewässerungAktiv */, true);
          setState('0_userdata.0.Bewässerung.PVEinfluss' /* PVEinfluss */, 9, true);
          setState('0_userdata.0.Bewässerung.Zähler' /* Zähler */, 0, true);
          console.debug('Starte Bewässerung Vormittag');
        }
      }
      // Timezone 2
      if (compareTime('12:00', null, '>=', null) && compareTime('17:00', null, '<', null) && getState('0_userdata.0.Bewässerung.Aktiv').val == true) {
        console.debug('Timezone 2');
        setState('0_userdata.0.Bewässerung.Timezone' /* Timezone */, 2, true);
        if (getState('linktap.0.03444023004B1200.13414023004B1200.InstantModeDuration').val != getState('0_userdata.0.Bewässerung.maxBewässerungszeit').val) {
          setState('linktap.0.03444023004B1200.13414023004B1200.InstantModeDuration' /* Duration for instant mode (min.1  - max. 1439) */, parseFloat(getState('0_userdata.0.Bewässerung.maxBewässerungszeit').val), true);
          console.debug('Duration angepasst');
          await wait(16000);
        }
        if (getState('0_userdata.0.Bewässerung.BewässerungAktiv').val == false) {
          setState('linktap.0.03444023004B1200.13414023004B1200.StartInstantMode' /* Starts instant mode. (Set duration in state 'InstantModeDuration' */, true);
          setState('0_userdata.0.Bewässerung.BewässerungAktiv' /* BewässerungAktiv */, true);
          setState('0_userdata.0.Bewässerung.PVEinfluss' /* PVEinfluss */, 9, true);
          setState('0_userdata.0.Bewässerung.Zähler' /* Zähler */, 0, true);
          console.debug('Starte Bewässerung Nachmittag');
        }
      }
      // Timezone 3
      if (compareTime('17:00', null, '>=', null) && compareTime('21:00', null, '<', null) && getState('0_userdata.0.Bewässerung.Aktiv').val == true) {
        console.debug('Timezone 3');
